interface QueryBadgesSignature {
  /**
   * Creates a query to retrieve a list of badges.
   *
   * The `queryBadges()` method builds a query to retrieve a list of badges and returns a `BadgesQueryBuilder` object.
   *
   * The returned object contains the query definition, which is typically used to run the query using the `find()` method.
   *
   * You can refine the query by chaining `BadgesQueryBuilder` methods onto the query. `BadgesQueryBuilder` methods enable you to sort, filter, and control the results `queryBadges()` returns.
   *
   * `queryBadges()` runs with these `BadgesQueryBuilder` defaults, which you can override:
   *
   * - limit(50)
   * - descending("_createdDate")
   *
   * The methods that are chained to `queryBadges()` are applied in the order they're called. For example, if you apply ascending('title') and then descending('id'), the results are sorted first by the title, and then, if there are multiple results with the same title, the items are sorted by ID.
   */
  (): BadgesQueryBuilder;
}

