/**
 * Creates a badge.
 * @param badge - Badge to create.
 * @public
 * @requiredField badge
 * @requiredField badge.backgroundColor
 * @requiredField badge.textColor
 * @requiredField badge.title
 * @permissionId BADGES.BADGE_CREATE
 * @applicableIdentity APP
 * @returns Created badge.
 * @fqn wix.badges.v4.Badges.CreateBadge
 */
export async function createBadge(
  badge: NonNullablePaths<Badge, `backgroundColor` | `textColor` | `title`, 0>
): Promise<Badge> {
  // @ts-ignore
  const { httpClient, sideEffects } = arguments[1] as {
    httpClient: HttpClient;
    sideEffects?: any;
  };

  const payload = transformPaths(
    renameKeysFromSDKRequestToRESTRequest({ badge: badge }),
    [
      {
        transformFn: transformSDKImageToRESTImage,
        paths: [{ path: 'badge.icon' }],
      },
    ]
  );

  const reqOpts = ambassadorWixBadgesV4Badge.createBadge(payload);

  sideEffects?.onSiteCall?.();
  try {
    const result = await httpClient.request(reqOpts);
    sideEffects?.onSuccess?.(result);

    return renameKeysFromRESTResponseToSDKResponse(
      transformPaths(result.data, [
        {
          transformFn: transformRESTImageToSDKImage,
          paths: [{ path: 'badge.icon' }],
        },
      ])
    )?.badge!;
  } catch (err: any) {
    const transformedError = sdkTransformError(
      err,
      {
        spreadPathsToArguments: {},
        explicitPathsToArguments: { badge: '$[0]' },
        singleArgumentUnchanged: false,
      },
      ['badge']
    );
    sideEffects?.onError?.(err);

    throw transformedError;
  }
}

